// @options: {"max_output_tokens": 30000, "timeout_ms": 60000}

const dump = await tools.bash({ command: "for f in $(find src -type f -name '*.js' | sort); do echo \"===== $f\"; cat \"$f\"; done", timeout: 15 });
const cfg = await tools.bash({ command: "for f in config/*.json; do echo \"===== $f\"; cat \"$f\"; done", timeout: 15 });

function splitDump(out) {
  const files = {};
  let cur = null;
  for (const raw of out.split("\n")) {
    const m = raw.match(/^===== (\S+)\s*$/);
    if (m) { cur = m[1]; files[cur] = []; continue; }
    if (cur !== null) files[cur].push(raw);
  }
  return files;
}
const files = splitDump(dump.output);
const cfgFiles = splitDump(cfg.output);

console.log("=== SOURCE FILES ===");
for (const [f, ls] of Object.entries(files)) {
  console.log("--- " + f);
  ls.forEach((l, i) => console.log(String(i + 1).padStart(3) + "| " + l));
}
console.log("=== CONFIG FILES ===");
for (const [f, ls] of Object.entries(cfgFiles)) console.log("--- " + f + "\n" + ls.join("\n"));

// ---------- legacyLog call-site analysis ----------
const stripLine = (s) => s
  .replace(/\/\*[\s\S]*?\*\//g, "")
  .replace(/\/\/.*$/, "")
  .replace(/'(?:[^'\\]|\\.)*'/g, "''")
  .replace(/"(?:[^"\\]|\\.)*"/g, '""')
  .replace(/`(?:[^`\\]|\\.)*`/g, "``");

const KEYWORDS = new Set(["if","for","while","switch","catch","return","else","do","try","typeof","new","await","yield","in","of","delete","void","instanceof"]);
function findDefs(s) {
  const defs = [];
  let m;
  const pats = [
    /function\s*\*?\s*([A-Za-z_$][\w$]*)\s*\(/g,
    /(?:const|let|var)\s+([A-Za-z_$][\w$]*)\s*=\s*(?:async\s*)?(?:function\b|\([^)]*\)\s*=>|[A-Za-z_$][\w$]*\s*=>)/g,
    /^\s*(?:async\s+)?(?:static\s+|get\s+|set\s+)?([A-Za-z_$][\w$]*)\s*\([^)]*\)\s*\{/g,
  ];
  for (const re of pats) while ((m = re.exec(s))) if (!KEYWORDS.has(m[1])) defs.push(m[1]);
  return defs;
}

const callers = [];
const detail = [];
for (const [f, lines] of Object.entries(files)) {
  let depth = 0;
  const stack = [];
  lines.forEach((line, idx) => {
    const s = stripLine(line);
    const defs = findDefs(s);
    const net = ((s.match(/\{/g) || []).length) - ((s.match(/\}/g) || []).length);
    const prev = depth;
    depth += net;
    for (const d of defs) stack.push({ name: d, open: prev + 1 });
    const isLegacyDef = defs.includes("legacyLog");
    let pos = -1;
    while ((pos = s.indexOf("legacyLog(", pos + 1)) !== -1) {
      if (isLegacyDef) continue; // the definition itself, not a call
      const enc = stack.length ? stack[stack.length - 1].name : "(top-level)";
      detail.push(f + ":" + (idx + 1) + " inside " + enc + " :: " + line.trim());
      if (!callers.some(c => c.file === f && c.fn === enc)) callers.push({ file: f, fn: enc });
    }
    while (stack.length && depth < stack[stack.length - 1].open) stack.pop();
  });
}
console.log("=== legacyLog CALL SITES ===");
detail.forEach(d => console.log(d));
console.log("total call sites: " + detail.length);
console.log("callers: " + callers.map(c => c.file + ":" + c.fn).join("; "));

// ---------- config key usage ----------
function walk(obj, prefix, out) {
  for (const k of Object.keys(obj)) {
    const path = prefix ? prefix + "." + k : k;
    out.push(path);
    if (obj[k] && typeof obj[k] === "object" && !Array.isArray(obj[k])) walk(obj[k], path, out);
  }
  return out;
}
const srcAll = Object.entries(files).map(([f, ls]) => ls.join("\n")).join("\n");
console.log("=== CONFIG KEY USAGE (in src) ===");
const unused = [];
for (const [f, ls] of Object.entries(cfgFiles)) {
  let obj;
  try { obj = JSON.parse(ls.join("\n")); } catch (e) { console.log(f + " PARSE ERROR " + e.message); continue; }
  for (const path of walk(obj, "", [])) {
    const leaf = path.split(".").pop();
    const used = srcAll.includes(leaf);
    console.log((used ? "USED  " : "UNUSED") + "  " + f + " :: " + path);
    if (!used) unused.push(f + " :: " + path);
  }
}
console.log("unused keys: " + (unused.join("; ") || "(none)"));
return "done";
